SELECT * FROM customer;
--. Revenue Analysis -
-- Compared total revenue generated by male and female customers
select gender, sum(purchase_amount) as total_revenue  
     from customer
	 group by gender;

--2 . discount& spending analysis - 
-- identifing discount user whose purchase amount were at or above the overall average
SELECT
    customer_id,
    purchase_amount
FROM customer
WHERE discount_applied = 'Yes'
AND purchase_amount >= (
    SELECT AVG(purchase_amount)
    FROM customer
);
--3.product rating analysis-
--ranking the top  5 products by average review rating
SELECT
    item_purchased,
   round (AVG(review_rating)::numeric,2) AS "Average Product Rating"
FROM customer
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC
LIMIT 5;

SELECT * FROM customer;
--4. shipping analysis-
-- compared average purchase amount for standard and express shipping
select shipping_type, round(avg(purchase_amount),2)
     from customer
	 where shipping_type in ('Standard','Express')
	 group by shipping_type;
--5 sub analysis
select subscription_status,
       count(customer_id) as total_customers,
       round(avg(purchase_amount),2) as avg_spend,
       round(sum(purchase_amount),2) as total_revenue
from customer
group by subscription_status
order by total_revenue, avg_spend desc;


-- discount analysis


select item_purchased,
       round(
           100.0*sum(
               case when discount_applied ='Yes' then 1
               else 0 end )/count(*),2 )
               as discount_rate
       from customer
       group by item_purchased
       order by discount_rate desc
       limit 5;

-- customer segmentation
with customer_type as
(
    select customer_id, previous_purchases,
           case when previous_purchases=1 then 'New'
                when previous_purchases between 2 and 10 then 'Returning'
                else 'Loyal'
           end as customer_segment
    from customer
)

SELECT
    CASE
        WHEN previous_purchases = 1 THEN 'New'
        WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
        ELSE 'Loyal'
    END AS customer_segment,
    COUNT(*) AS number_of_customers
FROM customer
GROUP BY customer_segment
ORDER BY customer_segment;

WITH item_counts AS
(
    SELECT
        category,
        item_purchased,
        COUNT(customer_id) AS total_orders,
        ROW_NUMBER() OVER (
            PARTITION BY category
            ORDER BY COUNT(customer_id) DESC
        ) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)

SELECT
    item_rank,
    category,
    item_purchased,
    total_orders
FROM item_counts
WHERE item_rank <= 3
ORDER BY category, item_rank;


select subscription_status,
count(customer_id) as repeated_buyers
from customer
where previous_purchases>5
group by subscription_status;



select age_group, sum(purchase_amount) as total_revenue

from customer
group by age_group
order by total_revenue desc;




			
	 


	 
	 
	 

